buggy.string_overflow_itemsize_and_expandtabs_:
import numpy as np

results = {}

# 1) Huge S itemsize parsing
try:
    dt = np.dtype('S')(2**61)
    results['dtype_S_itemsize_2pow61'] = {
        'dtype': str(dt),
        'itemsize': int(dt.itemsize),
        'repr': repr(dt)
    }
except Exception as e:
    results['dtype_S_itemsize_2pow61'] = {'exc_type': type(e).__name__, 'exc': str(e)}

# 2) expandtabs huge tabsize on S
try:
    arr = np.array(['\t'], dtype='S')
    out = np.strings.expandtabs(arr, 2**61)
    # Record minimal structured info to avoid huge memory allocations
    results['expandtabs_tabsize_2pow61'] = {
        'out_dtype': str(out.dtype),
        'out_shape': tuple(out.shape),
        'out_first': out.ravel()[0].decode('utf-8', errors='replace') if out.size else None,
    }
except Exception as e:
    results['expandtabs_tabsize_2pow61'] = {'exc_type': type(e).__name__, 'exc': str(e)}

probe(results)

